import{_ as p,W as t,s as o,u as d,I as s,ah as r,w as a,Z as i,A as l}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const w=JSON.parse('{"title":"在 Linux 中如何删除文件中的空行 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中如何删除文件中的空行 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中如何删除文件中的空行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中如何删除文件中的空行 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190211 How To Remove-Delete The Empty Lines In A File In Linux","title":"在 Linux 中如何删除文件中的空行","tag":"201903"},"relativePath":"201903/20190211 How To Remove-Delete The Empty Lines In A File In Linux.md","filePath":"[post].md"}'),c={name:"201903/20190211 How To Remove-Delete The Empty Lines In A File In Linux.md"};function u(g,e,b,m,h,x){const n=t("Link");return d(),o("div",null,[e[22]||(e[22]=s("h1",{id:"在-linux-中如何删除文件中的空行",tabindex:"-1"},[a("在 Linux 中如何删除文件中的空行 "),s("a",{class:"header-anchor",href:"#在-linux-中如何删除文件中的空行","aria-label":"Permalink to 在 Linux 中如何删除文件中的空行"},"​")],-1)),e[23]||(e[23]=s("p",null,"有时你可能需要在 Linux 中删除某个文件中的空行。如果是的，你可以使用下面方法中的其中一个。有很多方法可以做到，但我在这里只是列举一些简单的方法。",-1)),e[24]||(e[24]=s("p",null,[a("你可能已经知道 "),s("code",null,"grep"),a("、"),s("code",null,"awk"),a(" 和 "),s("code",null,"sed"),a(" 命令是专门用来处理文本数据的工具。")],-1)),s("p",null,[e[3]||(e[3]=a("如果你想了解更多关于这些命令的文章，请访问这几个 URL：")),i(n,{href:"https://www.2daygeek.com/create-a-file-in-specific-certain-size-linux/"},{default:l(()=>e[0]||(e[0]=[a("在 Linux 中创建指定大小的文件的几种方法")])),_:1}),e[4]||(e[4]=a("，")),i(n,{href:"https://www.2daygeek.com/linux-command-to-create-a-file/"},{default:l(()=>e[1]||(e[1]=[a("在 Linux 中创建一个文件的几种方法")])),_:1}),e[5]||(e[5]=a(" 以及 ")),i(n,{href:"https://www.2daygeek.com/empty-a-file-delete-contents-lines-from-a-file-remove-matching-string-from-a-file-remove-empty-blank-lines-from-a-file/"},{default:l(()=>e[2]||(e[2]=[a("在 Linux 中删除一个文件中的匹配的字符串")])),_:1}),e[6]||(e[6]=a("。"))]),e[25]||(e[25]=r(`<p>这些属于高级命令，它们可用在大多数 shell 脚本中执行所需的操作。</p><p>下列 5 种方法可以做到。</p><ul><li><code>sed</code>：过滤和替换文本的流编辑器。</li><li><code>grep</code>：输出匹配到的行。</li><li><code>cat</code>：合并文件并打印内容到标准输出。</li><li><code>tr</code>：替换或删除字符。</li><li><code>awk</code>：awk 工具用于执行 awk 语言编写的程序，专门用于文本处理。</li><li><code>perl</code>：Perl 是一种用于处理文本的编程语言。</li></ul><p>我创建了一个 <code>2daygeek.txt</code> 文件来测试这些命令。下面是文件的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat 2daygeek.txt</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>He got two GIRL babys.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>现在一切就绪，我们准备开始用多种方法来验证。</p><h3 id="使用-sed-命令" tabindex="-1">使用 sed 命令 <a class="header-anchor" href="#使用-sed-命令" aria-label="Permalink to 使用 sed 命令">​</a></h3><p><code>sed</code> 是一个<ruby>流编辑器<rt>stream editor</rt></ruby>。流编辑器是用来编辑输入流（文件或管道）中的文本的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sed &#39;/^$/d&#39; 2daygeek.txt</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span>He got two GIRL babes.</span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>以下是命令展开的细节：</p><ul><li><code>sed</code>： 该命令本身。</li><li><code>//</code>： 标记匹配范围。</li><li><code>^</code>： 匹配字符串开头。</li><li><code>$</code>： 匹配字符串结尾。</li><li><code>d</code>： 删除匹配的字符串。</li><li><code>2daygeek.txt</code>： 源文件名。</li></ul><h3 id="使用-grep-命令" tabindex="-1">使用 grep 命令 <a class="header-anchor" href="#使用-grep-命令" aria-label="Permalink to 使用 grep 命令">​</a></h3><p><code>grep</code> 可以通过正则表达式在文件中搜索。该表达式可以是一行或多行空行分割的字符，<code>grep</code> 会打印所有匹配的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ grep . 2daygeek.txt</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>$ grep -Ev &quot;^$&quot; 2daygeek.txt</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>$ grep -v -e &#39;^$&#39; 2daygeek.txt</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span>He got two GIRL babes.</span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>以下是命令展开的细节：</p><ul><li><code>grep</code>： 该命令本身。</li><li><code>.</code>： 替换任意字符。</li><li><code>^</code>： 匹配字符串开头。</li><li><code>$</code>： 匹配字符串结尾。</li><li><code>E</code>： 使用扩展正则匹配模式。</li><li><code>e</code>： 使用常规正则匹配模式。</li><li><code>v</code>： 反向匹配。</li><li><code>2daygeek.txt</code>： 源文件名。</li></ul><h3 id="使用-awk-命令" tabindex="-1">使用 awk 命令 <a class="header-anchor" href="#使用-awk-命令" aria-label="Permalink to 使用 awk 命令">​</a></h3><p><code>awk</code> 可以执行使用 awk 语言写的脚本，大多是专用于处理文本的。awk 脚本是一系列 <code>awk</code> 命令和正则的组合。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk NF 2daygeek.txt</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>$ awk &#39;!/^$/&#39; 2daygeek.txt</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>$ awk &#39;/./&#39; 2daygeek.txt</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span>He got two GIRL babes.</span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>以下是命令展开的细节：</p><ul><li><code>awk</code>： 该命令本身。</li><li><code>//</code>： 标记匹配范围。</li><li><code>^</code>： 匹配字符串开头。</li><li><code>$</code>： 匹配字符串结尾。</li><li><code>.</code>： 匹配任意字符。</li><li><code>!</code>： 删除匹配的字符串。</li><li><code>2daygeek.txt</code>： 源文件名。</li></ul><h3 id="使用-cat-和-tr-命令-组合" tabindex="-1">使用 cat 和 tr 命令 组合 <a class="header-anchor" href="#使用-cat-和-tr-命令-组合" aria-label="Permalink to 使用 cat 和 tr 命令 组合">​</a></h3><p><code>cat</code> 是<ruby>串联（拼接）<rt>concatenate</rt></ruby>的简写。经常用于在 Linux 中读取一个文件的内容。</p><p><code>cat</code> 是在类 Unix 系统中使用频率最高的命令之一。它提供了常用的三个处理文本文件的功能：显示文件内容、将多个文件拼接成一个，以及创建一个新文件。</p><p><code>tr</code> 可以将标准输入中的字符转换，压缩或删除，然后重定向到标准输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat 2daygeek.txt | tr -s &#39;\\n&#39;</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span>He got two GIRL babes.</span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>以下是命令展开的细节：</p><ul><li><code>cat</code>： cat 命令本身。</li><li><code>tr</code>： tr 命令本身。</li><li><code>|</code>： 管道符号。它可以将前面的命令的标准输出作为下一个命令的标准输入。</li><li><code>s</code>： 替换标数据集中任意多个重复字符为一个。</li><li><code>\\n</code>： 添加一个新的换行。</li><li><code>2daygeek.txt</code>： 源文件名。</li></ul><h3 id="使用-perl-命令" tabindex="-1">使用 perl 命令 <a class="header-anchor" href="#使用-perl-命令" aria-label="Permalink to 使用 perl 命令">​</a></h3><p>Perl 表示<ruby>实用的提取和报告语言<rt>Practical Extraction and Reporting Language</rt></ruby>。Perl 在初期被设计为一个专用于文本处理的编程语言，现在已扩展应用到 Linux 系统管理，网络编程和网站开发等多个领域。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ perl -ne &#39;print if /\\S/&#39; 2daygeek.txt</span></span>
<span class="line"><span>2daygeek.com is a best Linux blog to learn Linux.</span></span>
<span class="line"><span>It&#39;s FIVE years old blog.</span></span>
<span class="line"><span>This website is maintained by Magesh M, it&#39;s licensed under CC BY-NC 4.0.</span></span>
<span class="line"><span>He got two GIRL babes.</span></span>
<span class="line"><span>Her names are Tanisha &amp; Renusha.</span></span></code></pre></div><p>以下是命令展开的细节：</p><ul><li><code>perl</code>： perl 命令。</li><li><code>n</code>： 逐行读入数据。</li><li><code>e</code>： 执行某个命令。</li><li><code>print</code>： 打印信息。</li><li><code>if</code>： if 条件分支。</li><li><code>//</code>： 标记匹配范围。</li><li><code>\\S</code>： 匹配任意非空白字符。</li><li><code>2daygeek.txt</code>： 源文件名。</li></ul><hr>`,34)),s("p",null,[e[8]||(e[8]=a("via: ")),i(n,{href:"https://www.2daygeek.com/remove-delete-empty-lines-in-a-file-in-linux/"},{default:l(()=>e[7]||(e[7]=[a("https://www.2daygeek.com/remove-delete-empty-lines-in-a-file-in-linux/")])),_:1})]),s("p",null,[e[13]||(e[13]=a("作者：")),i(n,{href:"https://www.2daygeek.com/author/magesh/"},{default:l(()=>e[9]||(e[9]=[a("Magesh Maruthamuthu")])),_:1}),e[14]||(e[14]=a(" 选题：")),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>e[10]||(e[10]=[a("lujun9972")])),_:1}),e[15]||(e[15]=a(" 译者：")),i(n,{href:"https://github.com/pityonline"},{default:l(()=>e[11]||(e[11]=[a("pityonline")])),_:1}),e[16]||(e[16]=a(" 校对：")),i(n,{href:"https://github.com/wxy"},{default:l(()=>e[12]||(e[12]=[a("wxy")])),_:1})]),s("p",null,[e[19]||(e[19]=a("本文由 ")),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>e[17]||(e[17]=[a("LCTT")])),_:1}),e[20]||(e[20]=a(" 原创编译，")),i(n,{href:"https://linux.cn/"},{default:l(()=>e[18]||(e[18]=[a("Linux中国")])),_:1}),e[21]||(e[21]=a(" 荣誉推出"))])])}const L=p(c,[["render",u]]);export{w as __pageData,L as default};
